import React, { useState } from 'react';
import axios from 'axios';
import '../estilos/LoginRegister.css';

// Cambia el puerto si tu backend no usa el 5000
const API_BASE_URL = 'http://localhost:5000/api/auth';

const LoginRegister = () => {
  const [isLogin, setIsLogin] = useState(true);
  const [formData, setFormData] = useState({
    matricula: '',
    correo: '',
    password: '',
    confirmPassword: '',
    recoveryEmail: ''
  });
  const [errors, setErrors] = useState({});
  const [message, setMessage] = useState('');
  const [showTemporaryBlock, setShowTemporaryBlock] = useState(false);
  const [showRecovery, setShowRecovery] = useState(false);
  const [recoverySuccess, setRecoverySuccess] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  // ──────────────── VALIDACIONES ────────────────
  const validateEmail = (email) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  const validatePassword = (password) => {
    const hasUpperCase = /[A-Z]/.test(password);
    const hasNumber = /\d/.test(password);
    const hasSpecialChar = /[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/.test(password);
    return password.length >= 8 && hasUpperCase && hasNumber && hasSpecialChar;
  };

  // ──────────────── CAMBIO DE CAMPOS ────────────────
  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
    if (errors[name]) setErrors({ ...errors, [name]: '' });
    setMessage('');
  };

  // ──────────────── LOGIN / REGISTRO ────────────────
  const handleSubmit = async (e) => {
    e.preventDefault();
    const newErrors = {};
    setMessage('');

    // Validaciones locales
    if (isLogin) {
      if (!formData.matricula) newErrors.matricula = 'La matrícula es requerida';
      if (!formData.password) newErrors.password = 'La contraseña es requerida';
    } else {
      if (!formData.matricula) newErrors.matricula = 'La matrícula es requerida';
      else if (formData.matricula.length < 5) newErrors.matricula = 'Matrícula no válida';
      if (!formData.correo) newErrors.correo = 'El correo es requerido';
      else if (!validateEmail(formData.correo)) newErrors.correo = 'Correo no válido';
      if (!formData.password) newErrors.password = 'La contraseña es requerida';
      else if (!validatePassword(formData.password))
        newErrors.password = '8+ caracteres, 1 mayúscula, 1 número y 1 signo';
      if (formData.password !== formData.confirmPassword)
        newErrors.confirmPassword = 'Las contraseñas no coinciden';
    }

    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }

    setIsLoading(true);

    try {
      const url = isLogin ? `${API_BASE_URL}/login` : `${API_BASE_URL}/register`;
      const payload = isLogin
        ? { matricula: formData.matricula, password: formData.password }
        : { matricula: formData.matricula, correo: formData.correo, password: formData.password };

      const response = await axios.post(url, payload);

      if (isLogin) {
        localStorage.setItem('userToken', response.data.token);
        setMessage('¡Inicio de sesión exitoso! Redirigiendo...');
        // TODO: agrega aquí tu redirección, ejemplo:
        // window.location.href = '/dashboard';
      } else {
        setMessage('Registro exitoso. Ahora puedes iniciar sesión.');
        toggleMode();
      }
    } catch (error) {
      const backendMessage = error.response?.data?.message;
      if (error.response?.status === 403 && backendMessage?.includes('bloqueada')) {
        setShowTemporaryBlock(true);
        setTimeout(() => setShowTemporaryBlock(false), 5000);
      } else if (backendMessage) {
        setMessage(`Error: ${backendMessage}`);
      } else {
        setMessage('Error de conexión con el servidor.');
      }
    } finally {
      setIsLoading(false);
    }
  };

  // ──────────────── RECUPERAR CONTRASEÑA ────────────────
  const handleRecoverySubmit = async (e) => {
    e.preventDefault();
    const newErrors = {};
    setMessage('');

    if (!formData.recoveryEmail) newErrors.recoveryEmail = 'Correo requerido';
    else if (!validateEmail(formData.recoveryEmail))
      newErrors.recoveryEmail = 'Correo no válido';

    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }

    setIsLoading(true);
    try {
      await axios.post(`${API_BASE_URL}/forgot-password`, {
        correo: formData.recoveryEmail
      });
      setRecoverySuccess(true);
    } catch (error) {
      const backendMessage = error.response?.data?.message;
      if (error.response?.status === 404) {
        setErrors({ recoveryEmail: 'Este correo no está registrado' });
      } else if (backendMessage) {
        setMessage(`Error: ${backendMessage}`);
      } else {
        setMessage('Error de conexión.');
      }
    } finally {
      setIsLoading(false);
    }
  };

  // ──────────────── AUXILIARES ────────────────
  const handleRecoverPassword = () => {
    setShowRecovery(true);
    setErrors({});
    setRecoverySuccess(false);
    setMessage('');
  };

  const handleBackToLogin = () => {
    setShowRecovery(false);
    setRecoverySuccess(false);
    setErrors({});
    setMessage('');
  };

  const toggleMode = () => {
    setIsLogin(!isLogin);
    setFormData({
      matricula: '',
      correo: '',
      password: '',
      confirmPassword: '',
      recoveryEmail: ''
    });
    setErrors({});
    setShowTemporaryBlock(false);
    setMessage('');
  };

  // ──────────────── PANTALLA RECUPERACIÓN ────────────────
  if (showRecovery) {
    return (
      <div className="recovery-container">
        <div className="recovery-card">
          <div className="recovery-header">
            <div className="logo-title">
              <div className="logo">
                <svg viewBox="0 0 3000 3000" className="logo-svg">
                  <path fill="currentColor" d="M1119,796c472.75-7.672..." />
                </svg>
              </div>
              <h1 className="main-title">BIBLIOTECA YEAK8</h1>
            </div>
          </div>

          {recoverySuccess ? (
            <div className="success-message">
              <div className="success-icon">✅</div>
              <h2>Correo Enviado Exitosamente</h2>
              <p>
                Hemos enviado un enlace a <strong>{formData.recoveryEmail}</strong>.
              </p>
              <button onClick={handleBackToLogin} className="btn-back">
                Volver al Inicio de Sesión
              </button>
            </div>
          ) : (
            <form onSubmit={handleRecoverySubmit} className="recovery-form">
              <div className="input-group recovery-input">
                <div className="input-icon">📧</div>
                <input
                  type="email"
                  name="recoveryEmail"
                  value={formData.recoveryEmail}
                  onChange={handleChange}
                  className={errors.recoveryEmail ? 'error' : ''}
                  placeholder="tu.correo@ejemplo.com"
                />
              </div>
              {errors.recoveryEmail && (
                <div className="error-message">{errors.recoveryEmail}</div>
              )}
              <button type="submit" className="btn-recovery" disabled={isLoading}>
                {isLoading ? 'ENVIANDO...' : 'ENVIAR ENLACE'}
              </button>
              <div className="recovery-options">
                <button type="button" onClick={handleBackToLogin} className="back-btn">
                  ← Volver al Inicio de Sesión
                </button>
              </div>
            </form>
          )}
        </div>
      </div>
    );
  }

  // ──────────────── PANTALLA LOGIN / REGISTRO ────────────────
  return (
    <div className={`auth-container ${isLogin ? 'login-mode' : 'register-mode'}`}>
      <div className="background-elements">
        <div className="circle circle-1"></div>
        <div className="circle circle-2"></div>
        <div className="circle circle-3"></div>
        <div className="wave"></div>
      </div>

      <div className="auth-card">
        <div className="auth-header">
          <div className="logo-title">
            <div className="logo">
              <svg viewBox="0 0 3000 3000" className="logo-svg">
                <path fill="currentColor" d="M1119,796c472.75-7.672..." />
              </svg>
            </div>
            <h1 className="main-title">BIBLIOTECA YEAK8</h1>
          </div>
          <div className="login-welcome">
            <h2>{isLogin ? '¡Bienvenido de vuelta!' : 'REGISTRO EXCLUSIVO ESTUDIANTES'}</h2>
            <p>{isLogin ? 'Ingresa a tu cuenta' : 'Crea tu cuenta de estudiante'}</p>
          </div>
        </div>

        {message && (
          <div className={`alert ${message.includes('exitoso') ? 'alert-success' : 'alert-error'}`}>
            {message.includes('exitoso') ? '✅' : '❌'} {message}
          </div>
        )}

        {showTemporaryBlock && (
          <div className="alert alert-warning">
            <div className="alert-icon">⚠️</div>
            <strong>Cuenta bloqueada temporalmente. Intenta en 5 minutos.</strong>
          </div>
        )}

        <form onSubmit={handleSubmit} className="auth-form">
          {isLogin ? (
            <>
              <div className="input-group">
                <div className="input-icon">🎓</div>
                <input
                  type="text"
                  name="matricula"
                  value={formData.matricula}
                  onChange={handleChange}
                  placeholder="Tu matrícula"
                  disabled={isLoading}
                />
              </div>
              {errors.matricula && <div className="error-message">{errors.matricula}</div>}

              <div className="input-group">
                <div className="input-icon">🔒</div>
                <input
                  type="password"
                  name="password"
                  value={formData.password}
                  onChange={handleChange}
                  placeholder="Tu contraseña"
                  disabled={isLoading}
                />
              </div>
              {errors.password && <div className="error-message">{errors.password}</div>}

              <button type="submit" className="btn-login" disabled={isLoading}>
                {isLoading ? 'VERIFICANDO...' : 'INICIAR SESIÓN'}
              </button>

              <button type="button" className="recover-btn" onClick={handleRecoverPassword}>
                ¿Olvidaste tu contraseña?
              </button>
            </>
          ) : (
            <>
              <div className="form-section">
                <label>Matrícula</label>
                <input
                  type="text"
                  name="matricula"
                  value={formData.matricula}
                  onChange={handleChange}
                  disabled={isLoading}
                />
                {errors.matricula && <div className="error-message">{errors.matricula}</div>}
              </div>

              <div className="form-section">
                <label>Correo Electrónico</label>
                <input
                  type="email"
                  name="correo"
                  value={formData.correo}
                  onChange={handleChange}
                  disabled={isLoading}
                />
                {errors.correo && <div className="error-message">{errors.correo}</div>}
              </div>

              <div className="form-section">
                <label>Contraseña</label>
                <input
                  type="password"
                  name="password"
                  value={formData.password}
                  onChange={handleChange}
                  disabled={isLoading}
                />
                {errors.password && <div className="error-message">{errors.password}</div>}
              </div>

              <div className="form-section">
                <label>Confirmar Contraseña</label>
                <input
                  type="password"
                  name="confirmPassword"
                  value={formData.confirmPassword}
                  onChange={handleChange}
                  disabled={isLoading}
                />
                {errors.confirmPassword && (
                  <div className="error-message">{errors.confirmPassword}</div>
                )}
              </div>

              <button type="submit" className="btn-register" disabled={isLoading}>
                {isLoading ? 'REGISTRANDO...' : 'REGISTRAR'}
              </button>
            </>
          )}
        </form>

        <div className="toggle-section">
          <p>
            {isLogin ? '¿No tienes una cuenta?' : '¿Ya tienes una cuenta?'}
            <button type="button" onClick={toggleMode} className="toggle-btn">
              {isLogin ? 'Regístrate' : 'Inicia Sesión'}
            </button>
          </p>
        </div>
      </div>
    </div>
  );
};

export default LoginRegister;
